<?php
namespace qqworld_collector\module\engine; class xpath { var $DOMDocument; var $DOMXPath; public function loadHTML($html) { $html = mb_convert_encoding($html, 'HTML-ENTITIES', 'UTF-8'); $html = preg_replace('/<!\[CDATA\[([\s\S]*?)\]\]>/i', '$1', $html); $this->DOMDocument = new \DOMDocument(); @$this->DOMDocument->loadHTML($html); } public function query($xpath, $limit=0) { $DOMXPath = new \DOMXPath($this->DOMDocument); $nodes = $DOMXPath->query($xpath); $content = array(); foreach ($nodes as $index => $node) { if ($limit && $index-1>$limit) break; $children = $node->childNodes; $nodesContent = ''; foreach ($children as $child) { $tmp_doc = new \DOMDocument(); $tmp_doc->appendChild($tmp_doc->importNode($child, false)); $nodesContent .= html_entity_decode($tmp_doc->saveHTML()); } $content[] = $nodesContent; } return $content; } }